// In src/connection/client.ts

async subscribe(params?: SubscribeRequestParams): Promise<Subscription> {
  // ... existing request logic ...

  const sendAck = (ackParams: SubscriptionAckParams) => {
    this.notify(NOTIFICATION_METHODS.SUBSCRIBE_ACK, ackParams);
  };

  const subscription = createSubscription(
    result.subscriptionId,
    () => this.unsubscribe(result.subscriptionId),
    { filter: params?.filter },
    sendAck
  );

  // Check server capabilities
  const serverCaps = this.serverCapabilities?.streaming;
  subscription._setServerSupportsAck(serverCaps?.supportsAck ?? false);

  this.#subscriptions.set(result.subscriptionId, subscription);
  return subscription;
}
