### Replay Flow
- Track `lastSyncTimestamp` per peer during normal operation
- On reconnect, after buffer drain, request replay
- Use `map/replay` with `afterTimestamp` parameter
- Process replayed events through normal event handling
- Emit `replayStarted` and `replayCompleted` events

### Implementation
```typescript
private async #replayFromPeer(peerId: string): Promise<void> {
  const lastSync = this.#lastSyncTimestamps.get(peerId);
  if (!lastSync || !this.#options.replay?.enabled) return;

  this.#emitReconnectionEvent({ type: 'replayStarted', peerId });

  const result = await this.#connection.sendRequest<ReplayRequestParams, ReplayResponseResult>(
    'map/replay',
    {
      afterTimestamp: lastSync,
      eventTypes: this.#options.replay.eventTypes,
      maxEvents: this.#options.replay.maxEvents ?? 1000,
    }
  );

  // Process replayed events...

  this.#emitReconnectionEvent({ 
    type: 'replayCompleted', 
    peerId, 
    eventsReplayed: result.events.length 
  });
}
```

